// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VerificationFindings) predicate.VerificationFindings {
	return predicate.VerificationFindings(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VerificationFindings) predicate.VerificationFindings {
	return predicate.VerificationFindings(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VerificationFindings) predicate.VerificationFindings {
	return predicate.VerificationFindings(sql.NotPredicates(p))
}
